// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "I have a my apps linux container running at 192.168.100.125. could you remake the app using tanstack and have the state of it persist with a local sqlite database. also use React for the UI with components from: https://www.reactbits.dev/. after you are done could you deploy it onto the container."
// Changes: Project list – create, import JSON as new project, rename, duplicate, delete; Aurora/ShinyText/CountUp hero.
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Background animation pauses under reduced motion and has a visible pause/play button (remembered), renders
//          at dpr 1 without pointer tracking; no backdrop blur on stat tiles; CSS cards; in-page rename/delete dialogs;
//          card buttons described by the project name; focus moves to the next card (or the list heading) after delete.

import { ClientOnly, Link, createFileRoute, useNavigate, useRouter } from '@tanstack/react-router'
import { useServerFn } from '@tanstack/react-start'
import { useLayoutEffect, useRef, useState, type FormEvent } from 'react'
import { useConfirm, usePrompt } from '#/components/ConfirmDialog'
import { useAnimationPause } from '#/components/hooks'
import Aurora from '#/components/reactbits/Aurora'
import CountUp from '#/components/reactbits/CountUp'
import ShinyText from '#/components/reactbits/ShinyText'
import { formatTime } from '#/components/HistoryTab'
import { useToast } from '#/components/Toasts'
import { Button, Card, DangerButton, PrimaryButton, TextInput } from '#/components/ui'
import { PROJECT_NAME_MAX, parseProjectFile, projectNameFromFile } from '#/lib/project'
import { createProjectFn, deleteProjectFn, duplicateProjectFn, listProjectsFn, renameProjectFn } from '#/server/projects.functions'

export const Route = createFileRoute('/')({
  loader: () => listProjectsFn(),
  component: Home,
})

function Stat({ value, label }: { value: number; label: string }) {
  return (
    <div className="rounded-2xl border border-white/10 bg-canvas/80 px-5 py-3">
      <CountUp to={value} duration={1.1} className="text-2xl font-semibold tabular-nums text-zinc-100" />
      <div className="text-xs text-zinc-400">{label}</div>
    </div>
  )
}

function Home() {
  const projects = Route.useLoaderData()
  const router = useRouter()
  const navigate = useNavigate()
  const toast = useToast()
  const confirm = useConfirm()
  const prompt = usePrompt()
  const { paused, toggle: toggleAnimation } = useAnimationPause()
  const create = useServerFn(createProjectFn)
  const rename = useServerFn(renameProjectFn)
  const duplicate = useServerFn(duplicateProjectFn)
  const remove = useServerFn(deleteProjectFn)
  const [name, setName] = useState('')
  const [busy, setBusy] = useState(false)
  const fileRef = useRef<HTMLInputElement>(null)
  const listHeadingRef = useRef<HTMLHeadingElement>(null)
  const renameRefs = useRef(new Map<string, HTMLButtonElement>())
  // After rename/delete (buttons were disabled while busy): the project whose first button gets focus (null = heading).
  const focusAfter = useRef<string | null | undefined>(undefined)

  useLayoutEffect(() => {
    const target = focusAfter.current
    if (target === undefined || busy) return
    focusAfter.current = undefined
    ;((target !== null && renameRefs.current.get(target)) || listHeadingRef.current)?.focus()
  }, [projects, busy])

  const run = async (fn: () => Promise<void>, failTitle: string) => {
    setBusy(true)
    try {
      await fn()
    } catch (err) {
      toast({ title: failTitle, description: err instanceof Error ? err.message : String(err), tone: 'bad' })
    } finally {
      setBusy(false)
    }
  }

  const onCreate = (e: FormEvent) => {
    e.preventDefault()
    void run(async () => {
      const project = await create({ data: { name: name.trim() || 'Nový projekt' } })
      // AI generated by: Claude Code / claude-opus-5-5
      // Prompt: "LL by teraz mala pouzivat gramatiku, ktoru si vytvorim v tabulke definicia"
      // Changes: Projects open on the Definition tab, where the grammar is entered.
      await navigate({ to: '/p/$projectId', params: { projectId: project.id }, search: { tab: 'def' } })
    }, 'Projekt sa nepodarilo vytvoriť')
  }

  const onImport = (file: File) =>
    run(async () => {
      // AI generated by: Claude Code / claude-opus-5-5
      // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
      // Changes: Shared file parser (Slovak errors, version migrations); long file names are cut to the name limit;
      //          oversized files are rejected before reading them.
      if (file.size > 4 * 1024 * 1024) throw new Error('Súbor je príliš veľký na projekt (max. 4 MB).')
      const parsed = parseProjectFile(await file.text())
      if (!parsed.ok) throw new Error(parsed.error)
      const project = await create({ data: { name: projectNameFromFile(file.name), data: parsed.data } })
      // AI generated by: Claude Code / claude-opus-5-5
      // Prompt: "LL by teraz mala pouzivat gramatiku, ktoru si vytvorim v tabulke definicia"
      // Changes: Projects open on the Definition tab, where the grammar is entered.
      await navigate({ to: '/p/$projectId', params: { projectId: project.id }, search: { tab: 'def' } })
    }, 'Import zlyhal')

  const onRename = async (p: (typeof projects)[number]) => {
    const next = await prompt({ title: 'Premenovať projekt', label: 'Nový názov projektu', initial: p.name, maxLength: PROJECT_NAME_MAX, confirmLabel: 'Premenovať' })
    if (!next || next === p.name) return
    await run(async () => {
      await rename({ data: { id: p.id, name: next } })
      focusAfter.current = p.id
      await router.invalidate()
    }, 'Premenovanie zlyhalo')
  }

  const onDelete = async (p: (typeof projects)[number], index: number) => {
    const ok = await confirm({
      title: 'Zmazať projekt?',
      body: <>Projekt „{p.name}“ sa natrvalo zmaže aj s celou históriou verzií.</>,
      confirmLabel: 'Zmazať natrvalo',
      tone: 'danger',
    })
    if (!ok) return
    const neighbour = projects[index + 1] ?? projects[index - 1]
    await run(async () => {
      await remove({ data: { id: p.id } })
      focusAfter.current = neighbour ? neighbour.id : null
      await router.invalidate()
      toast({ title: 'Projekt zmazaný', description: p.name, tone: 'info' })
    }, 'Mazanie zlyhalo')
  }

  const totals = projects.reduce((acc, p) => ({ rules: acc.rules + p.llRules, snapshots: acc.snapshots + p.snapshots }), { rules: 0, snapshots: 0 })

  return (
    <div className="relative">
      <div aria-hidden="true" className="pointer-events-none absolute inset-x-0 top-0 h-[420px] overflow-hidden opacity-70">
        <ClientOnly>
          <Aurora
            colorStops={['#4f46e5', '#0ea5e9', '#8b5cf6']}
            amplitude={1}
            blend={0.55}
            speed={0.5}
            paused={paused}
            dpr={1}
            mouseInteraction={false}
          />
        </ClientOnly>
        <div className="absolute inset-0 bg-gradient-to-b from-transparent via-canvas/40 to-canvas" />
      </div>

      <main className="relative mx-auto max-w-6xl px-4 pt-20 pb-16 sm:px-6">
        {/* WCAG 2.2.2: the looping background (and title shine) can be stopped; label switches, no aria-pressed. */}
        <ClientOnly>
          <Button onClick={toggleAnimation} className="absolute top-4 right-4 text-xs sm:right-6">
            <span aria-hidden="true">{paused ? '▶' : '❚❚'}</span>
            {paused ? 'Spustiť animáciu' : 'Pozastaviť animáciu'}
          </Button>
        </ClientOnly>
        <h1 className="text-4xl font-bold tracking-tight sm:text-5xl">
          <ShinyText text="IFJ26 Table Maker" color="#c7cbd6" shineColor="#ffffff" speed={3.5} disabled={paused} />
        </h1>
        <p className="mt-3 max-w-2xl text-zinc-400">
          Návrh LL tabuľky a precedenčnej tabuľky pre prekladač IFJ26. Všetka práca sa priebežne ukladá do SQLite databázy na
          serveri.
        </p>

        <div className="mt-8 flex flex-wrap gap-3">
          <Stat value={projects.length} label="projektov" />
          <Stat value={totals.rules} label="LL pravidiel spolu" />
          <Stat value={totals.snapshots} label="uložených verzií" />
        </div>

        <form onSubmit={onCreate} className="mt-10 flex flex-wrap items-center gap-2">
          <TextInput value={name} onChange={(e) => setName(e.target.value)} placeholder="Názov nového projektu" className="max-w-sm font-sans! text-sm!" aria-label="Názov projektu" />
          <PrimaryButton type="submit" disabled={busy}>
            Vytvoriť projekt
          </PrimaryButton>
          <Button onClick={() => fileRef.current?.click()} disabled={busy}>
            Importovať .json…
          </Button>
          <input
            ref={fileRef}
            type="file"
            accept=".json,application/json"
            hidden
            onChange={(e) => {
              const file = e.target.files?.[0]
              e.target.value = ''
              if (file) void onImport(file)
            }}
          />
        </form>

        <h2 ref={listHeadingRef} tabIndex={-1} className="mt-10 rounded text-sm font-semibold tracking-wide text-zinc-300">
          Projekty
        </h2>
        {projects.length === 0 ? (
          <p className="mt-3 text-sm text-zinc-400">Zatiaľ žiadne projekty. Vytvor nový alebo importuj JSON z pôvodnej HTML verzie.</p>
        ) : (
          <ul className="mt-3 grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
            {projects.map((p, index) => (
              <li key={p.id} className="flex min-w-0 flex-col">
                <Card className="flex flex-1 flex-col p-5">
                  <Link
                    id={`project-${p.id}-title`}
                    to="/p/$projectId"
                    params={{ projectId: p.id }}
                    // AI generated by: Claude Code / claude-opus-5-5
                    // Prompt: "LL by teraz mala pouzivat gramatiku, ktoru si vytvorim v tabulke definicia"
                    // Changes: Open projects on the Definition tab.
                    search={{ tab: 'def' }}
                    className="text-lg font-semibold text-zinc-100 after:absolute after:inset-0 after:content-[''] hover:text-indigo-200"
                  >
                    {p.name}
                  </Link>
                  <div className="mt-1 text-xs text-zinc-400">Upravené {formatTime(p.updatedAt)}</div>
                  <div className="mt-3 flex flex-wrap gap-1.5 text-[11px] text-zinc-400">
                    <span className="rounded-full bg-white/5 px-2 py-0.5">{p.llRules} LL pravidiel</span>
                    <span className="rounded-full bg-white/5 px-2 py-0.5">{p.precSize ? `${p.precSize}×${p.precSize} prec.` : 'bez prec. tabuľky'}</span>
                    <span className="rounded-full bg-white/5 px-2 py-0.5">{p.snapshots} verzií</span>
                  </div>
                  <div className="relative z-[2] mt-4 flex flex-wrap gap-2">
                    <Button
                      ref={(el) => {
                        if (el) renameRefs.current.set(p.id, el)
                        else renameRefs.current.delete(p.id)
                      }}
                      disabled={busy}
                      aria-describedby={`project-${p.id}-title`}
                      onClick={() => void onRename(p)}
                    >
                      Premenovať
                    </Button>
                    <Button
                      disabled={busy}
                      aria-describedby={`project-${p.id}-title`}
                      onClick={() =>
                        void run(async () => {
                          await duplicate({ data: { id: p.id } })
                          await router.invalidate()
                        }, 'Duplikovanie zlyhalo')
                      }
                    >
                      Duplikovať
                    </Button>
                    <DangerButton disabled={busy} aria-describedby={`project-${p.id}-title`} onClick={() => void onDelete(p, index)}>
                      Zmazať
                    </DangerButton>
                  </div>
                </Card>
              </li>
            ))}
          </ul>
        )}
      </main>
    </div>
  )
}
